@startuml

class Department {}

class Room {}

class Bed {
  + Category : StayCategory
}

class StayCategory {
  + Price : double
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class Stay {
  + StartDate : date
  + Status : string
}

class Registration {
  + RegistrationDate : date
  + IdentificationData : string
}

class Assessment {
  + Needs : string
  + ResultingStayType : StayType
}

class WaitingListPosition {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Decision : string
  + IsValidated : boolean
}

class Invoice {
  + Date : date
  + Amount : double
  + OutstandingAmount : double
  + Status : string
}

class Payment {
  + Amount : double
  + Date : datetime
}

class CreditNote {
  + Amount : double
}

Department "1" -- "*" Room
Room "1" -- "*" Bed
Bed "1" -- "1" StayCategory
Inhabitant "1" -- "*" Registration
Inhabitant "1" -- "*" Stay
Stay "*" -- "1" StayCategory
Inhabitant "1" -- "*" Assessment
Inhabitant "1" -- "*" WaitingListPosition
StayType "1" -- "*" WaitingListPosition
Inhabitant "1" -- "*" Proposal
StayType "1" -- "*" Proposal
Inhabitant "1" -- "*" Invoice
Invoice "1" -- "*" Payment
Invoice "1" -- "0..1" CreditNote

@enduml

